//! A document of a kind Komainu is made for: the equations and the numerical method of
//! a channel-flow solver (fractional step, Runge-Kutta + Crank-Nicolson, FFT-based Poisson solver).
//! Run from the repository root: `cargo run --example sample`.
//!
//! The template (`sample.md`) reads like the document; everything it refers to is defined here.
//! Terms that appear several times (e.g. the explicit terms at two Runge-Kutta steps) are
//! generated by functions, and notations are chosen in one place.

use komainu::{Document, Expr};

const TEMPLATE: &str = "examples/sample/sample.md";

// Notations of the Runge-Kutta coefficients. Change them here and the whole document follows.
/// Explicit terms evaluated at the step `k`.
const ALPHA: &str = r"\alpha^k";
/// Explicit terms evaluated at the step `k - 1`.
const BETA: &str = r"\beta^k";
/// Implicit terms.
const GAMMA: &str = r"\gamma^k";

/// The time level a quantity is evaluated at; it becomes a superscript.
#[derive(Clone, Copy)]
enum Level {
    Current,
    Next,
    Star,
    K,
    Kp1,
    Km1,
}

impl Level {
    fn suffix(self) -> &'static str {
        match self {
            Self::Current => "n",
            Self::Next => "next",
            Self::Star => "star",
            Self::K => "k",
            Self::Kp1 => "kp1",
            Self::Km1 => "km1",
        }
    }

    fn superscript(self) -> &'static str {
        match self {
            Self::Current => "n",
            Self::Next => "n + 1",
            Self::Star => "*",
            Self::K => "k",
            Self::Kp1 => "k + 1",
            Self::Km1 => "k - 1",
        }
    }
}

/// Registers `base` at `level` (e.g. `u_i^{k - 1}`) as the symbol `<name>_<level>`.
#[track_caller]
fn at(doc: &mut Document, name: &str, base: &str, level: Level) -> Expr {
    doc.symbol(
        &format!("{name}_{}", level.suffix()),
        &format!("{base}^{{{}}}", level.superscript()),
    )
}

fn partial(target: &Expr, variable: &Expr) -> Expr {
    Expr::partial_derivative(target, variable)
}

/// The second derivative `d/dv (d f / dv)`.
fn second(f: &Expr, variable: &Expr) -> Expr {
    Expr::partial_derivative_operator(partial(f, variable), variable)
}

/// Physical constants and coordinates shared by the generated terms.
struct Constants {
    x: Expr,
    y: Expr,
    x_j: Expr,
    nu: Expr,
    kappa: Expr,
    delta: Expr,
}

impl Constants {
    /// Buoyancy (Boussinesq approximation, nondimensional): the temperature in y direction.
    fn buoyancy(&self, temperature: &Expr) -> Expr {
        &self.delta * temperature
    }

    /// Explicit terms of the momentum equation (everything but pressure and the diffusion in y).
    fn explicit_momentum(&self, u_i: &Expr, u_j: &Expr, temperature: &Expr) -> Expr {
        -u_j * partial(u_i, &self.x_j)
            + &self.nu * second(u_i, &self.x)
            + self.buoyancy(temperature)
    }

    /// Explicit terms of the temperature equation (everything but the diffusion in y).
    fn explicit_temperature(&self, u_j: &Expr, temperature: &Expr) -> Expr {
        -u_j * partial(temperature, &self.x_j) + &self.kappa * second(temperature, &self.x)
    }

    /// Implicit (Crank-Nicolson) diffusion in y: `1/2 * diffusivity * d/dy (d(a + b)/dy)`.
    /// The factor 1/2 is kept outside, which keeps the fractions of the output flat.
    fn implicit_diffusion(&self, diffusivity: &Expr, a: &Expr, b: &Expr) -> Expr {
        Expr::fraction(Expr::integer(1), Expr::integer(2)) * diffusivity * second(&(a + b), &self.y)
    }
}

fn build(template: String) -> Document {
    let mut doc = Document::new(template);
    doc.operator("partial", 2, |args| partial(&args[0], &args[1]));
    // Integral with bounds: `definite_integral(lower, upper, integrand, variable)`.
    doc.operator("definite_integral", 4, |args| {
        Expr::definite_integral(&args[0], &args[1], &args[2], &args[3])
    });

    // Coordinates and time.
    doc.symbol("time", "t");
    let x = doc.symbol("x", "x");
    let y = doc.symbol("y", "y");
    let x_i = doc.symbol("x_i", "x_i");
    let x_j = doc.symbol("x_j", "x_j");
    at(&mut doc, "time", "t", Level::Current);
    at(&mut doc, "time", "t", Level::Next);
    let time_step = doc.symbol("time_step", r"\Delta t");
    doc.symbol("dx", r"\Delta x");

    // Fields.
    let velocity = doc.symbol("velocity", "u_i");
    let velocity_j = doc.symbol("velocity_j", "u_j");
    let temperature = doc.symbol("temperature", "T");
    let pressure = doc.symbol("pressure", "p");
    let psi = doc.symbol("psi", r"\psi");
    let velocity_star = at(&mut doc, "velocity", "u_i", Level::Star);
    let velocity_n = at(&mut doc, "velocity", "u_i", Level::Current);
    at(&mut doc, "velocity", "u_i", Level::Next);
    let velocity_k = at(&mut doc, "velocity", "u_i", Level::K);
    at(&mut doc, "velocity", "u_i", Level::Kp1);
    let velocity_j_n = at(&mut doc, "velocity_j", "u_j", Level::Current);
    let temperature_n = at(&mut doc, "temperature", "T", Level::Current);
    let temperature_k = at(&mut doc, "temperature", "T", Level::K);
    let temperature_kp1 = at(&mut doc, "temperature", "T", Level::Kp1);
    // Abbreviations of the explicit terms at the steps n, k and k - 1.
    for level in [Level::Current, Level::K, Level::Km1] {
        at(&mut doc, "momentum_term", "H_i", level);
        at(&mut doc, "temperature_term", "F", level);
    }
    let pressure_k = at(&mut doc, "pressure", "p", Level::K);
    at(&mut doc, "pressure", "p", Level::Kp1);

    // Constants.
    // Nondimensional diffusivities.
    let prandtl = doc.symbol("prandtl", r"\mathrm{Pr}");
    let rayleigh = doc.symbol("rayleigh", r"\mathrm{Ra}");
    let one = Expr::integer(1);
    let nu = doc.def("nu", Expr::sqrt(Expr::fraction(&prandtl, &rayleigh)));
    let kappa = doc.def(
        "kappa",
        Expr::sqrt(Expr::fraction(&one, &prandtl * &rayleigh)),
    );
    doc.symbol("alpha", ALPHA);
    doc.symbol("beta", BETA);
    let gamma = doc.symbol("gamma", GAMMA);
    let delta = doc.symbol("delta", r"\delta_{i2}");
    let c = Constants {
        x,
        y,
        x_j: x_j.clone(),
        nu: nu.clone(),
        kappa: kappa.clone(),
        delta,
    };

    // Governing equations.
    doc.def("divergence", partial(&velocity, &x_i));
    // The terms of the right-hand side carry their sign (the minus is part of the term),
    // so that the template can simply add them.
    doc.def("advection", -&velocity_j * partial(&velocity, &x_j));
    doc.def("pressure_gradient", -partial(&pressure, &x_i));
    doc.def("diffusion", &nu * second(&velocity, &x_j));
    doc.def("buoyancy", c.buoyancy(&temperature));
    doc.def(
        "advection_temperature",
        -&velocity_j * partial(&temperature, &x_j),
    );
    doc.def("diffusion_temperature", &kappa * second(&temperature, &x_j));

    // Fractional step.
    doc.def("laplacian_psi", second(&psi, &x_i));

    // Runge-Kutta steps: the explicit terms are generated for a generic step by one function
    // (a different level, or a different equation, is one more call, not a retyped formula).
    doc.def(
        "explicit_momentum_n",
        c.explicit_momentum(&velocity_n, &velocity_j_n, &temperature_n),
    );
    doc.def(
        "explicit_temperature_n",
        c.explicit_temperature(&velocity_j_n, &temperature_n),
    );
    doc.def(
        "implicit_momentum",
        c.implicit_diffusion(&nu, &velocity_star, &velocity_k),
    );
    doc.def(
        "implicit_temperature",
        c.implicit_diffusion(&kappa, &temperature_kp1, &temperature_k),
    );
    doc.def("pressure_gradient_k", partial(&pressure_k, &x_i));
    doc.def("diffusion_y_psi", &nu * second(&psi, &c.y));
    doc.def(
        "poisson_rhs",
        Expr::fraction(&one, &gamma * &time_step) * partial(&velocity_star, &x_i),
    );

    // FFT-based Poisson solver.
    doc.symbol("rhs_hat", r"\hat{r}_{m, j}");
    doc.symbol("psi_hat_jm1", r"\hat{\psi}_{m, j - 1}");
    doc.symbol("psi_hat_j", r"\hat{\psi}_{m, j}");
    doc.symbol("psi_hat_jp1", r"\hat{\psi}_{m, j + 1}");
    doc.symbol("a_j", "a_j");
    doc.symbol("b_j", "b_j");
    doc.symbol("c_j", "c_j");
    doc.symbol("lambda_m", r"\lambda_m");
    doc.symbol("sin_m", r"\sin \frac{\pi m}{N_x}");

    doc
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let template = std::fs::read_to_string(TEMPLATE)?;
    let markdown = build(template).render()?;
    std::fs::create_dir_all("out")?;
    std::fs::write("out/sample.md", markdown)?;
    Ok(())
}
